import React from 'react';

// ⚠️ ඔයාගේ project එකේ logo image path එක තියෙන තැන:
// import logoImg from '../assets/logo.png'; 

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick, role = 'admin' }) {
  
  // 1️⃣ Admin Menu Items (Screenshot 1 Exact Names)
  const adminMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Manage Teachers', icon: '🧑‍🏫' },
    { name: 'Manage Students', icon: '🧑‍🎓' },
    { name: 'Manage Subjects', icon: '📚' }, 
    { name: 'Manage Timetable', icon: '🏫' },
    { name: 'Reports', icon: '📊' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 2️⃣ Teacher Menu Items (Screenshot 2 Exact Names)
  const teacherMenuItems = [
    { name: 'Dashboard Overview', icon: '🏠' },
    { name: 'Content Manager', icon: '📂' },
    { name: 'Quiz & Exam Manager', icon: '📝' },
    { name: 'Question Bank', icon: '📚' },
    { name: 'Forum & Activity Hub', icon: '🧩' },
    { name: 'View Reports', icon: '📊' },
    { name: 'Student Feedback', icon: '💬' },
    { name: 'My Profile Settings', icon: '👤' },
  ];

  // 3️⃣ Student Menu Items (Screenshot 3 Exact Names)
  const studentMenuItems = [
    { name: 'Overview', icon: '🏠' },
    { name: 'Study Materials', icon: '📚' },
    { name: 'Lesson Activities', icon: '🧩' },
    { name: 'Exams & Quizzes', icon: '📝' },
    { name: 'Class Timetable', icon: '🗓️' },
    { name: 'Feedback', icon: '💬' },
    { name: 'Settings', icon: '⚙️' },
  ];

  // 🔄 Role එක අනුව අදාළ Menu Items තේරීම
  let menuItems = adminMenuItems;
  if (role === 'teacher') menuItems = teacherMenuItems;
  if (role === 'student') menuItems = studentMenuItems;

  return (
    <aside style={styles.sidebar}>
      
      {/* 🟢 Header Section - Logo + Title */}
      <div style={styles.brandContainer}>
        {/* Logo Image එකක් ඇතුළත් කිරීමට: */}
        {/* <img src={logoImg} alt="Logo" style={styles.logoImage} /> */}
        <div>
          <h2 style={styles.brandTitle}>Aura Pen Saku</h2>
          <span style={styles.roleSubtext}>
            {role === 'teacher' ? 'TEACHER DASHBOARD' : role === 'student' ? 'STUDENT PORTAL' : 'ADMIN PORTAL'}
          </span>
        </div>
      </div>

      {/* 🟢 Dynamic Navigation Menu */}
      <div style={styles.menuList}>
        {menuItems.map((item) => {
          const isActive = currentSubPage === item.name;
          return (
            <button
              key={item.name}
              onClick={() => setCurrentSubPage(item.name)}
              style={{
                ...styles.navButton,
                backgroundColor: isActive ? 'rgba(255, 255, 255, 0.2)' : 'transparent',
                fontWeight: isActive ? 'bold' : 'normal',
              }}
            >
              <span style={{ fontSize: '18px' }}>{item.icon}</span>
              <span>{item.name}</span>
            </button>
          );
        })}
      </div>

      {/* 🔴 Bottom Logout Button */}
      <div style={styles.logoutContainer}>
        <button onClick={onLogoutClick} style={styles.logoutBtn}>
          {role === 'teacher' ? 'Logout Portal 🚪' : 'Logout 🚪'}
        </button>
      </div>

    </aside>
  );
}

const styles = {
  sidebar: {
    width: '260px',
    minWidth: '260px',
    height: '100vh',
    backgroundColor: '#0d5c2e', // Pure Green Background
    color: '#ffffff',
    display: 'flex',
    flexDirection: 'column',
    padding: '20px 14px',
    boxSizing: 'border-box',
    position: 'sticky',
    top: 0,
  },
  brandContainer: {
    paddingBottom: '14px',
    marginBottom: '10px',
    borderBottom: '1px solid rgba(255, 255, 255, 0.15)',
    display: 'flex',
    alignItems: 'center',
    gap: '10px',
  },
  logoImage: {
    width: '40px',
    height: '40px',
    objectFit: 'contain',
  },
  brandTitle: {
    margin: 0,
    fontSize: '20px',
    fontWeight: '800',
    color: '#ffffff',
    letterSpacing: '0.3px',
  },
  roleSubtext: {
    fontSize: '11px',
    fontWeight: '700',
    color: '#bbf7d0',
    letterSpacing: '0.8px',
    display: 'block',
    marginTop: '3px',
  },
  menuList: {
    flex: 1,
    display: 'flex',
    flexDirection: 'column',
    gap: '6px',
    overflowY: 'auto',
  },
  navButton: {
    width: '100%',
    textAlign: 'left',
    padding: '12px 14px',
    border: 'none',
    outline: 'none',
    borderRadius: '10px',
    color: '#ffffff',
    cursor: 'pointer',
    fontSize: '14.5px',
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    transition: 'background-color 0.15s ease',
  },
  logoutContainer: {
    paddingTop: '12px',
    marginTop: 'auto',
    borderTop: '1px solid rgba(255, 255, 255, 0.15)',
  },
  logoutBtn: {
    width: '100%',
    padding: '12px',
    backgroundColor: '#dc2626',
    color: '#ffffff',
    border: 'none',
    borderRadius: '10px',
    fontWeight: 'bold',
    fontSize: '14.5px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
  }
};
